```tsx
'use client';

import { useRef } from 'react';
import gsap from 'gsap';
import { useGSAP } from '@gsap/react';

gsap.registerPlugin(useGSAP);

type HeroProps = {
  title: string;
  subtitle: string;
};

export default function Hero({ title, subtitle }: HeroProps) {
  const scope = useRef<HTMLDivElement>(null);

  useGSAP(
    () => {
      const prefersReducedMotion = window.matchMedia(
        '(prefers-reduced-motion: reduce)'
      ).matches;

      if (prefersReducedMotion) {
        gsap.set(['[data-hero-title]', '[data-hero-subtitle]'], {
          opacity: 1,
          y: 0,
        });
        return;
      }

      gsap
        .timeline({ defaults: { ease: 'power3.out' } })
        .from('[data-hero-title]', {
          opacity: 0,
          y: 24,
          duration: 0.8,
        })
        .from(
          '[data-hero-subtitle]',
          {
            opacity: 0,
            y: 16,
            duration: 0.6,
          },
          '-=0.4'
        );
    },
    { scope }
  );

  return (
    <section
      ref={scope}
      className="flex min-h-[80vh] flex-col items-center justify-center gap-6 px-6 text-center"
    >
      <h1
        data-hero-title
        className="text-4xl font-semibold tracking-tight text-balance sm:text-6xl"
      >
        {title}
      </h1>
      <p
        data-hero-subtitle
        className="max-w-2xl text-lg text-pretty text-neutral-400 sm:text-xl"
      >
        {subtitle}
      </p>
    </section>
  );
}
```

Notas:
- Usa `useGSAP` (de `@gsap/react`, ya está en tus deps) en vez de `useEffect` + `gsap.context` manual: hace la limpieza sola al desmontar y respeta el scope del ref, que es el patrón recomendado por GSAP para React.
- Respeta `prefers-reduced-motion`: si el usuario lo tiene activado, el título y subtítulo aparecen directo sin animación.
- El timeline usa `.from()` con offset negativo (`-=0.4`) para que el subtítulo empiece a animarse antes de que termine el título — da la sensación de secuencia sin sentirse lento.
- Es un componente puro (recibe `title`/`subtitle` por props), sin nada de env ni fetch, así que no aplica la regla de env hardcodeado.

